mkdir -p src && cd src; for u in "https://www.nature.com/articles/s41598-024-60529-1.pdf" "https://www.nature.com/articles/s41598-017-14177-3.pdf" "https://media.springernature.com/full/springer-static/image/art%3A10.1038%2Fs41598-024-60529-1/MediaObjects/41598_2024_60529_Fig5_HTML.png"; do f=$(basename "$u" | sed 's/%3A/_/g;s/%2F/_/g'); curl -sS -L -m 60 -o "$f" -w "%{http_code} %{size_download} $f\n" "$u"; done; file *